import { Button } from "@/components/ui/button";
import InfoMenu from "@/components/ui/navbar-components/info-menu";
import Logo from "@/components/ui/navbar-components/logo";
import NotificationMenu from "@/components/ui/navbar-components/notification-menu";
import UserMenu from "@/components/ui/navbar-components/user-menu";
import {
	NavigationMenu,
	NavigationMenuItem,
	NavigationMenuLink,
	NavigationMenuList,
} from "@/components/ui/navigation-menu";
import {
	Popover,
	PopoverContent,
	PopoverTrigger,
} from "@/components/ui/popover";

// Navigation links array to be used in both desktop and mobile menus
const navigationLinks = [
	{ href: "#", label: "Home" },
	{ href: "#", label: "Features" },
	{ href: "#", label: "Pricing" },
	{ href: "#", label: "About" },
];

export default function Component() {
	return (
		<header className="border-b px-4 md:px-6">
			<div className="flex h-16 items-center justify-between gap-4">
				{/* Left side */}
				<div className="flex items-center gap-2">
					{/* Mobile menu trigger */}
					<Popover>
						<PopoverTrigger asChild>
							<Button
								className="group size-8 md:hidden"
								variant="ghost"
								size="icon"
							>
								<svg
									className="pointer-events-none"
									width={16}
									height={16}
									viewBox="0 0 24 24"
									fill="none"
									stroke="currentColor"
									strokeWidth="2"
									strokeLinecap="round"
									strokeLinejoin="round"
									xmlns="http://www.w3.org/2000/svg"
								>
									<path
										d="M4 12L20 12"
										className="origin-center -translate-y-[7px] transition-all duration-300 ease-[cubic-bezier(.5,.85,.25,1.1)] group-aria-expanded:translate-x-0 group-aria-expanded:translate-y-0 group-aria-expanded:rotate-[315deg]"
									/>
									<path
										d="M4 12H20"
										className="origin-center transition-all duration-300 ease-[cubic-bezier(.5,.85,.25,1.8)] group-aria-expanded:rotate-45"
									/>
									<path
										d="M4 12H20"
										className="origin-center translate-y-[7px] transition-all duration-300 ease-[cubic-bezier(.5,.85,.25,1.1)] group-aria-expanded:translate-y-0 group-aria-expanded:rotate-[135deg]"
									/>
								</svg>
							</Button>
						</PopoverTrigger>
						<PopoverContent align="start" className="w-36 p-1 md:hidden">
							<NavigationMenu className="max-w-none *:w-full">
								<NavigationMenuList className="flex-col items-start gap-0 md:gap-2">
									{navigationLinks.map((link, index) => (
										<NavigationMenuItem
											key={index}
											className="w-full"
										>
											<NavigationMenuLink
												href={link.href}
												className="py-1.5"
											>
												{link.label}
											</NavigationMenuLink>
										</NavigationMenuItem>
									))}
								</NavigationMenuList>
							</NavigationMenu>
						</PopoverContent>
					</Popover>
					{/* Main nav */}
					<div className="flex items-center gap-6">
						<a href="#" className="text-primary hover:text-primary/90">
							<Logo />
						</a>
						{/* Navigation menu */}
						<NavigationMenu className="max-md:hidden">
							<NavigationMenuList className="gap-2">
								{navigationLinks.map((link, index) => (
									<NavigationMenuItem key={index}>
										<NavigationMenuLink
											href={link.href}
											className="text-muted-foreground hover:text-primary py-1.5 font-medium"
										>
											{link.label}
										</NavigationMenuLink>
									</NavigationMenuItem>
								))}
							</NavigationMenuList>
						</NavigationMenu>
					</div>
				</div>
				{/* Right side */}
				<div className="flex items-center gap-4">
					<div className="flex items-center gap-2">
						{/* Info menu */}
						<InfoMenu />
						{/* Notification */}
						<NotificationMenu />
					</div>
					{/* User menu */}
					<UserMenu />
				</div>
			</div>
		</header>
	);
}

import * as React from "react";

import { cn } from "@/registry/utilities/cn";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

const buttonVariants = cva(
	"inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm text-white hover:text-gray-400 font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
	{
		variants: {
			variant: {
				simple:
					"bg-secondary relative z-10 bg-transparent hover:border-secondary hover:bg-secondary/50  border border-transparent dark:text-white text-sm md:text-sm transition font-medium duration-200  rounded-md px-4 py-2  flex items-center justify-center",
				default: "bg-primary text-primary-foreground hover:bg-primary/90",
				destructive:
					"bg-destructive text-destructive-foreground hover:bg-destructive/90",
				outline:
					"border border-input bg-background hover:bg-accent hover:text-accent-foreground",
				secondary:
					"bg-secondary text-secondary-foreground hover:bg-secondary/80",
				ghost: "hover:bg-accent hover:text-black hover:stroke-black dark:text-white text-black",
				link: "text-primary underline-offset-4 hover:underline",
			},
			size: {
				default: "h-10 px-4 py-2",
				sm: "h-9 rounded-md px-3",
				lg: "h-11 rounded-md px-8",
				icon: "h-10 w-10",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	}
);

export interface ButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement>,
		VariantProps<typeof buttonVariants> {
	asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
	({ className, variant, size, asChild = false, ...props }, ref) => {
		const Comp = asChild ? Slot : "button";
		return (
			<Comp
				className={cn(buttonVariants({ variant, size, className }))}
				ref={ref}
				{...props}
			/>
		);
	}
);
Button.displayName = "Button";

export { Button, buttonVariants };

import { ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

"use client";

import { useState } from "react";

import { Button } from "@/components/ui/button";
import {
	Popover,
	PopoverContent,
	PopoverTrigger,
} from "@/components/ui/popover";
import { BellIcon } from "lucide-react";

const initialNotifications = [
	{
		id: 1,
		user: "Chris Tompson",
		action: "requested review on",
		target: "PR #42: Feature implementation",
		timestamp: "15 minutes ago",
		unread: true,
	},
	{
		id: 2,
		user: "Emma Davis",
		action: "shared",
		target: "New component library",
		timestamp: "45 minutes ago",
		unread: true,
	},
	{
		id: 3,
		user: "James Wilson",
		action: "assigned you to",
		target: "API integration task",
		timestamp: "4 hours ago",
		unread: false,
	},
	{
		id: 4,
		user: "Alex Morgan",
		action: "replied to your comment in",
		target: "Authentication flow",
		timestamp: "12 hours ago",
		unread: false,
	},
	{
		id: 5,
		user: "Sarah Chen",
		action: "commented on",
		target: "Dashboard redesign",
		timestamp: "2 days ago",
		unread: false,
	},
	{
		id: 6,
		user: "Miky Derya",
		action: "mentioned you in",
		target: "Origin UI open graph image",
		timestamp: "2 weeks ago",
		unread: false,
	},
];

function Dot({ className }: { className?: string }) {
	return (
		<svg
			width="6"
			height="6"
			fill="currentColor"
			viewBox="0 0 6 6"
			xmlns="http://www.w3.org/2000/svg"
			className={className}
			aria-hidden="true"
		>
			<circle cx="3" cy="3" r="3" />
		</svg>
	);
}

export default function NotificationMenu() {
	const [notifications, setNotifications] = useState(initialNotifications);
	const unreadCount = notifications.filter((n) => n.unread).length;

	const handleMarkAllAsRead = () => {
		setNotifications(
			notifications.map((notification) => ({
				...notification,
				unread: false,
			}))
		);
	};

	const handleNotificationClick = (id: number) => {
		setNotifications(
			notifications.map((notification) =>
				notification.id === id
					? { ...notification, unread: false }
					: notification
			)
		);
	};

	return (
		<Popover>
			<PopoverTrigger asChild>
				<Button
					size="icon"
					variant="ghost"
					className="text-muted-foreground relative size-8 rounded-full shadow-none"
					aria-label="Open notifications"
				>
					<BellIcon size={16} aria-hidden="true" />
					{unreadCount > 0 && (
						<div
							aria-hidden="true"
							className="bg-primary absolute top-0.5 right-0.5 size-1 rounded-full"
						/>
					)}
				</Button>
			</PopoverTrigger>
			<PopoverContent className="w-80 p-1">
				<div className="flex items-baseline justify-between gap-4 px-3 py-2">
					<div className="text-sm font-semibold">Notifications</div>
					{unreadCount > 0 && (
						<button
							className="text-xs font-medium hover:underline"
							onClick={handleMarkAllAsRead}
						>
							Mark all as read
						</button>
					)}
				</div>
				<div
					role="separator"
					aria-orientation="horizontal"
					className="bg-border -mx-1 my-1 h-px"
				></div>
				{notifications.map((notification) => (
					<div
						key={notification.id}
						className="hover:bg-accent rounded-md px-3 py-2 text-sm transition-colors"
					>
						<div className="relative flex items-start pe-3">
							<div className="flex-1 space-y-1">
								<button
									className="text-foreground/80 text-left after:absolute after:inset-0"
									onClick={() =>
										handleNotificationClick(notification.id)
									}
								>
									<span className="text-foreground font-medium hover:underline">
										{notification.user}
									</span>{" "}
									{notification.action}{" "}
									<span className="text-foreground font-medium hover:underline">
										{notification.target}
									</span>
									.
								</button>
								<div className="text-muted-foreground text-xs">
									{notification.timestamp}
								</div>
							</div>
							{notification.unread && (
								<div className="absolute end-0 self-center">
									<span className="sr-only">Unread</span>
									<Dot />
								</div>
							)}
						</div>
					</div>
				))}
			</PopoverContent>
		</Popover>
	);
}

"use client";

import React from "react";

import { cn } from "@/registry/utilities/cn";
import * as AvatarPrimitive from "@radix-ui/react-avatar";

const Avatar = React.forwardRef<
	React.ElementRef<typeof AvatarPrimitive.Root>,
	React.ComponentPropsWithoutRef<typeof AvatarPrimitive.Root>
>(({ className, ...props }, ref) => (
	<AvatarPrimitive.Root
		ref={ref}
		className={cn(
			"relative flex h-10 w-10 shrink-0 overflow-hidden rounded-full",
			className
		)}
		{...props}
	/>
));
Avatar.displayName = AvatarPrimitive.Root.displayName;

const AvatarImage = React.forwardRef<
	React.ElementRef<typeof AvatarPrimitive.Image>,
	React.ComponentPropsWithoutRef<typeof AvatarPrimitive.Image>
>(({ className, ...props }, ref) => (
	<AvatarPrimitive.Image
		ref={ref}
		className={cn("aspect-square h-full w-full", className)}
		{...props}
	/>
));
AvatarImage.displayName = AvatarPrimitive.Image.displayName;

const AvatarFallback = React.forwardRef<
	React.ElementRef<typeof AvatarPrimitive.Fallback>,
	React.ComponentPropsWithoutRef<typeof AvatarPrimitive.Fallback>
>(({ className, ...props }, ref) => (
	<AvatarPrimitive.Fallback
		ref={ref}
		className={cn(
			"flex h-full w-full items-center justify-center rounded-full bg-muted",
			className
		)}
		{...props}
	/>
));
AvatarFallback.displayName = AvatarPrimitive.Fallback.displayName;

export { Avatar, AvatarImage, AvatarFallback };
